    out: dict[uuid.UUID, tuple[int, int, str | None]] = {}
    for run_id, by_status in status_histograms(
        session, run_ids, complete_runs_only=complete_runs_only
    ).items():
        passed = by_status.get("pass", 0)
        worst = worst_severity(by_status)
