    columns: list[str],
    top_n: int,
    secret_store: SecretStore,
) -> ProfileResult:
    """Profile `columns` of a natively-read Iceberg `table` on `connection` (#721)."""
    identifier = _iceberg_identifier(table, namespace)
    try:
