/**
 * Workspace-admin switch that leaves one table out of its connection's automatic coverage
 * (ADR 0047). Excluding pauses the table's automatic suite; it deletes nothing.
 */
export function CoverageBlock({
  assetId,
  excluded,
  onChanged,
